        ['nama' => 'Set Up Slide Show', 'cat' => 'bentang', 'desc' => 'Settings for how the show runs: presented by a speaker, browsed by one person at a kiosk, or looping without stopping.', 'langkah' => 'Slide Show → Set Up Slide Show → choose Show type. For an exhibition display: Browsed at a kiosk (full screen), which loops until Esc is pressed.', 'awas' => 'Kiosk mode needs slide timings (Rehearse Timings or After in Transitions). Without timings, the first slide stays on screen.'],
        ['nama' => 'Live Subtitles', 'cat' => 'bentang', 'desc' => 'Live captions of what you say, in the same language or translated.', 'langkah' => 'Slide Show → Subtitle Settings → Spoken Language, Subtitle Language, and position (default Below Slide). Select Always Use Subtitles to turn them on every time.', 'awas' => 'Needs a microphone and an Internet connection. Test in the actual room, because background noise lowers accuracy.'],
        ['nama' => 'Summary Zoom', 'cat' => 'bentang', 'desc' => 'A summary slide with a thumbnail for each section. Click a thumbnail to go to that section and return to the summary afterwards.', 'langkah' => 'Insert → Zoom → Summary Zoom → select the first slide of each section → Insert.', 'tip' => 'PowerPoint creates a new summary slide before the first slide you selected.'],
        ['nama' => 'Presenter View Tools', 'cat' => 'bentang', 'desc' => 'Buttons in Presenter View to see all slides, zoom into part of a slide, and black out the audience screen.', 'langkah' => 'In Presenter View: See all slides, Zoom into slide, or Black or unblack slide show. The enlarge text button below the notes pane makes your notes bigger.', 'tip' => 'Zoom into slide suits a dense table or chart that comes up during questions.'],

        // === SAVE AND SHARE ===
        ['nama' => 'Export PDF', 'cat' => 'fail', 'popular' => true, 'desc' => 'Share slides in a format whose layout does not change.', 'langkah' => 'File → Export → Create PDF/XPS Document → Create PDF/XPS. For handouts: Options → Publish what → Handouts.'],
        ['nama' => 'Export Video', 'cat' => 'fail', 'desc' => 'Turn the presentation, including recorded timings and narration, into an MP4 video.', 'langkah' => 'File → Export → Create a Video.'],
        ['nama' => 'Embed Fonts', 'cat' => 'fail', 'desc' => 'Carry custom fonts with the file so they are not substituted on other computers.', 'langkah' => 'File → Options → Save → select Embed fonts in the file.'],
        ['nama' => 'PDF with Notes', 'cat' => 'fail', 'desc' => 'A PDF with one slide and its notes on each page, for assessors who want to read the full argument.', 'langkah' => 'File → Print → Printer: Microsoft Print to PDF → Settings: Full Page Slides (arrow) → Notes Pages → Print.', 'awas' => 'File → Export → Create PDF/XPS with the default settings outputs the slides only, without notes.'],
        ['nama' => 'Create Handouts', 'cat' => 'fail', 'desc' => 'Send the slides and notes to an editable Word document, with notes next to or below each slide.', 'langkah' => 'File → Export → Create Handouts → Create Handouts → choose a page layout → OK.'],
        ['nama' => 'Inspect Document', 'cat' => 'fail', 'desc' => 'Find and remove comments, speaker notes, ink, off-slide objects, and personal information before sending a file.', 'langkah' => 'File → Info → Check for Issues → Inspect Document → select content types → Inspect → Remove All on the ones to remove.', 'awas' => 'Removed content might not come back with Undo. Run it on a copy of the file, not the original.'],
        ['nama' => 'Package Presentation for CD', 'cat' => 'fail', 'desc' => 'Copy the presentation with its linked files and TrueType fonts into one folder, so it opens correctly on another computer.', 'langkah' => 'File → Export → Package Presentation for CD → Package for CD → Options (choose files to include) → Copy to Folder → choose the USB drive → OK.', 'awas' => 'Most computers have no CD drive. Use Copy to Folder onto a USB drive, not Copy to CD. If there are no linked files, a PDF or video is easier to carry.'],

        // === VIDEO AND RECORDING ===
        ['nama' => 'Record Slide Show', 'cat' => 'rakam', 'popular' => true, 'desc' => 'Record your voice, camera, ink, and laser pointer together with each slide\'s timing, for lectures or online presentations.', 'langkah' => 'The Record button in the top-right corner, or Record → From Beginning / From Current Slide. Turn the camera and microphone on or off with the icons at the top.', 'tip' => 'Speaker notes appear at the top of the recording screen as a teleprompter.', 'awas' => 'Recorded timings make slides advance on their own when you present live. Remove them with Record → Clear Recording before a face-to-face class.'],
        ['nama' => 'Insert Video', 'cat' => 'rakam', 'desc' => 'Embed a video clip from your computer in a slide.', 'langkah' => 'Insert → Video → This Device → choose the file → Insert.', 'tip' => 'Use .mp4 files with H.264 video and AAC audio so they play on most computers.'],
        ['nama' => 'Video Playback Start', 'cat' => 'rakam', 'desc' => 'Set when a video starts playing: in the click sequence, automatically, or only when the video is clicked.', 'langkah' => 'Select the video → Playback → Start → In Click Sequence, Automatically, or When Clicked On.', 'tip' => 'In Click Sequence is the default. The video plays when you press a key or click to go to the next step.'],
        ['nama' => 'Trim Video', 'cat' => 'rakam', 'desc' => 'Cut unneeded footage from the start and end of a video without other software.', 'langkah' => 'Select the video → Playback → Trim Video → drag the green marker (start) and the red marker (end) → OK.', 'tip' => 'The trimmed parts are still in the file. Run Compress Media to remove them and make the file smaller.'],
        ['nama' => 'Compress Media', 'cat' => 'rakam', 'desc' => 'Reduce the size of embedded video and audio so the file is easy to send and open.', 'langkah' => 'File → Info → Compress Media → choose a compression level.', 'tip' => 'Video is the main cause of large presentation files. Compress before sending by email or uploading to a course portal.'],
        ['nama' => 'Record Audio', 'cat' => 'rakam', 'desc' => 'Record narration or a short explanation straight into one slide.', 'langkah' => 'Insert → Audio → Record Audio → name it → record → OK.'],
        ['nama' => 'Screen Recording', 'cat' => 'rakam', 'desc' => 'Record your computer screen, for example a software demonstration, and insert the recording in a slide.', 'langkah' => 'Insert → Screen Recording → Select Area → drag the area → Record.', 'tip' => 'Close notifications and personal tabs before recording. Everything inside the selected area is recorded.'],

        // === ACCESSIBILITY ===
        ['nama' => 'Check Accessibility', 'cat' => 'akses', 'popular' => true, 'desc' => 'Check slides for issues that make them hard for screen reader users or people with low vision, such as pictures without alt text and slides without titles.', 'langkah' => 'Review → Check Accessibility. The Accessibility pane lists errors and warnings with suggested fixes.', 'tip' => 'The status bar also shows a reminder when the file has accessibility issues.'],
        ['nama' => 'Reading Order', 'cat' => 'akses', 'desc' => 'The order in which a screen reader reads the objects on a slide. It follows the object list, not where objects sit on screen.', 'langkah' => 'Review → Check Accessibility → Warnings → Check reading order → arrow next to the slide number → Verify object order. Drag items, or use Move Up / Move Down.', 'awas' => 'Objects added later are usually read last even when they sit at the top of the slide. Check the order after adding objects.'],
        ['nama' => 'Mark as Decorative', 'cat' => 'akses', 'desc' => 'Mark decorative pictures or shapes so screen readers skip them.', 'langkah' => 'Right-click the object → View Alt Text → select Mark as decorative.', 'tip' => 'Suits color bars, frames, and background patterns. Pictures that carry information still need alt text.'],
        ['nama' => 'Hidden Slide Title', 'cat' => 'akses', 'desc' => 'A unique title for a slide that does not need a visible one, such as a full-picture slide. Screen readers and the slide list still read it.', 'langkah' => 'Review → Check Accessibility → Slide Title (arrow) → Add Hidden Slide Title → type the title.', 'awas' => 'Slides with the same title, such as "Findings" repeated, are hard to navigate. Give each slide a different title.'],
        ['nama' => 'Video Captions', 'cat' => 'akses', 'desc' => 'Add closed captions to an embedded video for deaf viewers or a noisy room.', 'langkah' => 'Select the video → Playback → Insert Captions → Insert Captions → choose the .vtt file → Insert.', 'tip' => 'Captions are stored in a .vtt text file prepared beforehand, by hand or with a caption tool.'],
        ['nama' => 'Accessible Link Text', 'cat' => 'akses', 'desc' => 'Link text that describes its destination, not "click here" or a long URL.', 'langkah' => 'Select the text → Insert → Link → type descriptive text in Text to display → ScreenTip for extra detail → OK.', 'pintasan' => 'Ctrl+K'],
        ['nama' => 'Text Contrast', 'cat' => 'akses', 'desc' => 'Enough color difference between text and background so slides read well on a projector and for color-blind viewers.', 'langkah' => 'Review → Check Accessibility → review contrast warnings → change the text or background color with Home → Font Color or Design → Format Background.', 'awas' => 'The checker does not catch every case, for example text in a transparent text box over a picture. Check those slides yourself.'],

        // === ACADEMIC SLIDES AND VIVA ===
        ['nama' => 'Backup Slides', 'cat' => 'akademik', 'popular' => true, 'desc' => 'Detail slides, such as full tables and statistical tests, kept after the conclusion to answer assessors\' questions.', 'langkah' => 'Home → Section → Add Section after the conclusion slide → name it Backup → select the slides in that section → Slide Show → Hide Slide.', 'tip' => 'During questions, type the backup slide number and press Enter to jump straight to it.'],
        ['nama' => 'Slide Zoom', 'cat' => 'akademik', 'desc' => 'A clickable slide thumbnail that jumps to that slide, for example from the method slide to a backup slide.', 'langkah' => 'Insert → Zoom → Slide Zoom → select the slide → Insert. Select the thumbnail and tick Return to Zoom on the Zoom tab so you come back afterwards.'],
        ['nama' => 'Insert Equation', 'cat' => 'akademik', 'desc' => 'An editable mathematical equation, not a picture of one that blurs when enlarged.', 'langkah' => 'Insert → Equation → type the equation or choose a structure from the Equation tab.', 'pintasan' => 'Alt+='],
        ['nama' => 'Rehearse with Coach', 'cat' => 'akademik', 'desc' => 'Private practice with feedback on your pace, filler words, and reading text off the slides.', 'langkah' => 'Slide Show → Rehearse with Coach → present as usual → read the report at the end.', 'tip' => 'Use it two or three days before the viva, then practise with Rehearse Timings to check you fit the time.'],
    ],
];
